// Header: YCloud-Signature: t=<unix_seconds>,s=<signature>
// The HMAC is computed over ts + '.' + the RAW body (W-E).
const body_text = String($('Body To Text').first().json.body_text ?? '');
const headers   = $('YCloud Webhook').first().json.headers ?? {};
const raw       = String(headers['ycloud-signature'] ?? '');

const parts = {};
for (const p of raw.split(',')) {
  const i = p.indexOf('=');
  if (i > 0) parts[p.slice(0, i).trim()] = p.slice(i + 1).trim();
}

const ts                = String(parts.t ?? '');
const receivedSignature = String(parts.s ?? '');

const now       = Math.floor(Date.now() / 1000);
const tsNum     = Number(ts);
const deviation = Number.isFinite(tsNum) && ts !== ''
  ? Math.abs(now - tsNum)
  : Number.MAX_SAFE_INTEGER;

return [{ json: {
  body_text,
  ts,
  received_signature: receivedSignature,
  deviation,
  has_signature: ts !== '' && receivedSignature !== '',
  to_sign: ts + '.' + body_text,
}}];

// The reason goes to the alert, NOT to the HTTP response.
// Telling signature apart from tolerance is what avoids chasing the HMAC
// when the problem is the host clock (W-C).
const j = $input.first().json ?? {};
const h = $('YCloud Webhook').first().json.headers ?? {};

let reason;
if (!j.has_signature)          reason = 'no YCloud-Signature header, or malformed';
else if (j.deviation > 300)    reason = 'timestamp out of tolerance (' + j.deviation + ' s) - check the n8n host clock';
else                           reason = 'the signature does not match';

const text = 'WEBHOOK REJECTED - 401\n\n'
  + 'Reason: ' + reason + '\n'
  + 'IP: ' + String(h['x-forwarded-for'] ?? 'unknown') + '\n'
  + 'The database was not touched.';

return [{ json: { text, reason } }];

// W-F. The payload comes from outside: only known fields are read, and they are trimmed.
const b = $('YCloud Webhook').first().json.body ?? {};
const m = b.whatsappMessage ?? {};
const type   = String(b.type ?? '');
const status = String(m.status ?? '');

// read also counts as delivered: the patient opened it, so it arrived.
// NO separate 'read' status is added: it would force touching the table's check
// constraint and every future alert would have to handle it, without deciding anything different.
const MAP = { delivered: 'delivered', read: 'delivered', failed: 'failed' };

const key = String(m.externalId ?? '').slice(0, 200);
let action = 'ignore';
let newStatus = '';
let alert = '';

if (type !== 'whatsapp.message.updated') {
  // The endpoint subscribed to a single event. If another one arrives, someone changed
  // the subscription in the YCloud panel and we want to know (INV-12).
  alert = 'WEBHOOK FOR AN UNSUBSCRIBED EVENT\n\nType: ' + type.slice(0, 80)
        + '\nThe database was not touched. Check the endpoint subscription in YCloud.';
} else if (status === 'sent') {
  action = 'ignore';   // it is what the sender already wrote; rewriting it adds nothing
} else if (key === '') {
  // Without an externalId the message is NOT ours: a person wrote it from the YCloud
  // inbox. There is no row to update and it is not an anomaly, so it is ignored
  // SILENTLY (correction of 2026-09-08).
  //
  // The "unknown key" alert is reserved for the different, serious case: an
  // externalId that DID arrive but is not in bot.sends. Mixing them up raised the
  // alarm every time someone answered a patient by hand, and an alarm that shouts
  // routinely teaches people to ignore it.
  action = 'ignore';
} else if (MAP[status]) {
  action = 'update';
  newStatus = MAP[status];
} else {
  alert = 'WEBHOOK WITH AN UNRECOGNIZED STATUS\n\nStatus: ' + status.slice(0, 40)
        + '\nKey: ' + (key || 'no externalId')
        + '\nThe database was not touched (INV-12: visible discard).';
}

const isFailure = newStatus === 'failed';

return [{ json: {
  action, status: newStatus, alert, key,
  ycloud_id:     String(m.id ?? '').slice(0, 100),
  wamid:         String(m.wamid ?? '').slice(0, 200),
  error_code:    isFailure ? String(m.errorCode ?? 'NO_CODE').slice(0, 50) : '',
  error_message: isFailure ? String(m.errorMessage ?? 'no detail').slice(0, 500) : '',
}}];

// The final select ALWAYS returns one row, and that is enough to tell
// the three outcomes apart without a second query (W-H).
const r        = $input.first().json ?? {};
const previous = r.previous_status ?? null;
const next     = r.new_status      ?? null;
const key       = $('Map Status').first().json.key;
const newStatus = $('Map Status').first().json.status;

let alert = '';

if (previous === null) {
  // The strangest thing that can happen: a SIGNED confirmation arrived for a
  // key that does not exist. Either a message went out with an externalId that is not
  // in the database, or someone managed to sign. Either one should ring a bell.
  alert = 'WEBHOOK WITH AN UNKNOWN KEY\n\n'
        + 'Key: ' + (key || '(empty)') + '\n'
        + 'It does not exist in bot.sends. Check: either a message went out with an externalId\n'
        + 'that is not in the database, or the endpoint received something we did not send.';
} else if (next === null && previous === 'reviewed') {
  alert = 'LATE CONFIRMATION FOR A CASE ALREADY REVIEWED\n\n'
        + 'Key: ' + key + '\n'
        + '"' + newStatus + '" arrived but you already closed it as reviewed.\n'
        + 'Not touched: the state machine never goes backwards. If it has to be reopened, do it by hand.';
}

return [{ json: { key, previous_status: previous, new_status: next, alert } }];
